+// What counts as the person's Notification Center click in the attended TXE-4684 case
+// (e2e/alerts.e2e.mjs, OKR_E2E_NC_LATE=1): only a click asked for. `asked` is when the run said
+// CLICK NOW (ms since the epoch); a click on the alert, or a macOS response for its request,
+// from before then is the banner clicked early, which is not the path under test, so it fails
+// the run rather than counting.
+
+/**
+ * The app's clicks on alert `id`, split at `asked`: `early` (any click before it) and `late`
+ * (a click in the same session at or after it).
+ */
+export function appClicks(events, id, asked) {
+  const clicks = events.filter((e) => e.type === 'alert-clicked' && e.id === id);
+  return {
+    early: clicks.filter((e) => Date.parse(e.t) < asked),
+    late: clicks.filter((e) => Date.parse(e.t) >= asked && e.sameSession === true),
+  };
+}
+
+/** A `log show --style compact` line's time, read as the Mac's local time, in ms. */
+export function logLineTime(line) {
+  const m = /^(\d{4})-(\d{2})-(\d{2}) (\d{2}):(\d{2}):(\d{2})\.(\d{3})/.exec(line);
+  if (!m) return NaN;
+  const [, y, mo, d, h, mi, s, ms] = m.map(Number);
+  return new Date(y, mo - 1, d, h, mi, s, ms).getTime();
+}
+
+/** usernoted's "Received response" lines for request `id`, split at `asked`. */
+export function osResponses(text, id, asked) {
+  const lines = text.split('\n').filter((l) => l.includes('Received response') && l.includes(`req:"${id}"`));
+  return {
+    early: lines.filter((l) => logLineTime(l) < asked),
+    late: lines.filter((l) => logLineTime(l) >= asked),
+  };
+}
+
+/** `log show --start` takes the Mac's local time, to the second. */
+export function localStamp(d) {
+  const z = (n) => String(n).padStart(2, '0');
+  return `${d.getFullYear()}-${z(d.getMonth() + 1)}-${z(d.getDate())} ${z(d.getHours())}:${z(d.getMinutes())}:${z(d.getSeconds())}`;
+}
+
+/**
+ * The alerts of `category` this run caused: received at or after `since` (ms) and not among
+ * `before` (the ids received before the run caused anything), so an alert left pending by an
+ * earlier run of the same account is never taken for this one.
+ */
+export function newAlerts(events, category, before, since) {
+  return [...new Set(events
+    .filter((e) => e.type === 'alert-received' && e.category === category && Date.parse(e.t) >= since && !before.has(e.id))
+    .map((e) => e.id))];
+}
+
+/**
+ * Writes the run's evidence into `out` (events copied from `events` if that file exists, then
+ * `electron` and `usernoted` as text). Throws if anything cannot be written.
+ */
+export function keepEvidence(fs, path, out, { events, electron, usernoted }) {
+  fs.mkdirSync(out, { recursive: true });
+  if (fs.existsSync(events)) fs.copyFileSync(events, path.join(out, 'nc-late-events.jsonl'));
+  fs.writeFileSync(path.join(out, 'nc-late-electron.log'), electron);
+  if (usernoted) fs.writeFileSync(path.join(out, 'nc-late-usernoted.log'), usernoted);

